exercicio.solucaoReferencia:
async function carregarUsuarios() {
  try {
    const res = await fetch('/api/usuarios');
    if (!res.ok) throw new Error('Falha ao buscar usuários');
    return await res.json();
  } catch (erro) {
    console.error(erro);
    return [];
  }
}
